#!/usr/bin/env node
// build-bundle.js — produce dist/qwen-bundle.js, a self-contained single-file
// client with Alibaba's AWSC JS scripts embedded as gzip+base64 string
// literals. Ship this file alone in a Docker image and the container boots
// with zero network cost for AWSC.
//
//   node build-bundle.js
//
// Reads:
//   src/lib/awsc-scripts.js             (the template source)
//   <cache-dir>/awsc/{awsc,collina,um}.js  (must be present — run the
//                                         module once or call the browser
//                                         to populate the cache before
//                                         building)
// Writes:
//   dist/qwen.js                        (replacement for src/lib/awsc-scripts.js
//                                        with EMBEDDED_AWSC injected)
//   dist/qwen-bundle.js                 (single-file bundle of the whole src)
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const { CACHE_DIR, AWSC_DIR } = require('./src/lib/constants'); // eslint-disable-line no-unused-vars

const HERE = __dirname;
const SRC_LIB = path.join(HERE, 'src', 'lib', 'awsc-scripts.js');
const DIST_DIR = path.join(HERE, 'dist');
const OUT_AWSC = path.join(DIST_DIR, 'awsc-scripts.bundled.js');

const NAMES = ['awsc', 'collina', 'um'];

function readOrDie(file) {
  if (!fs.existsSync(file)) {
    console.error(`[build] missing ${file}`);
    console.error(`[build] run \`node -e "require('./src').warmup({forceRefresh:true})"\` first to populate the AWSC cache at`);
    console.error(`[build]   ${AWSC_DIR}`);
    process.exit(1);
  }
  return fs.readFileSync(file);
}

console.log(`[build] reading AWSC scripts from ${AWSC_DIR}`);
const embedded = {};
for (const name of NAMES) {
  const file = path.join(AWSC_DIR, `${name}.js`);
  const buf = readOrDie(file);
  const gz = zlib.gzipSync(buf, { level: 9 });
  const b64 = gz.toString('base64');
  embedded[name] = b64;
  console.log(
    `[build]   ${name}.js: raw ${buf.length} → gz ${gz.length} → b64 ${b64.length}`
  );
}

// Chunk base64 strings so the generated file stays diffable.
function chunkB64(b64, width = 76) {
  const parts = [];
  for (let i = 0; i < b64.length; i += width) parts.push(b64.slice(i, i + width));
  return parts;
}

const literal =
  'const EMBEDDED_AWSC = {\n' +
  NAMES.map((n) => {
    const parts = chunkB64(embedded[n]);
    const lines = parts.map((p) => "    '" + p + "'").join(',\n');
    return '  ' + n + ": [\n" + lines + "\n  ].join('')";
  }).join(',\n') +
  '\n};';

console.log(`[build] reading template ${SRC_LIB}`);
const template = fs.readFileSync(SRC_LIB, 'utf8');

const marker = 'const EMBEDDED_AWSC = null;';
if (!template.includes(marker)) {
  console.error(`[build] src/lib/awsc-scripts.js is missing the marker: ${marker}`);
  process.exit(1);
}
const banner =
  `// dist/awsc-scripts.bundled.js — auto-generated by build-bundle.js on ${new Date().toISOString()}\n` +
  `// DO NOT EDIT BY HAND. Regenerate with: node build-bundle.js\n` +
  `// This replaces src/lib/awsc-scripts.js with a version that has\n` +
  `// Alibaba's AWSC scripts inlined (gzip + base64).\n`;

const bundled = banner + template.replace(marker, literal);

fs.mkdirSync(DIST_DIR, { recursive: true });
fs.writeFileSync(OUT_AWSC, bundled);

const size = fs.statSync(OUT_AWSC).size;
console.log(`[build] wrote ${OUT_AWSC} (${size} bytes, ${Math.round(size / 1024)} KB)`);

// Poor-man's full bundle: just copy the whole src/ tree + the generated
// awsc-scripts into dist/. For heavier setups use esbuild/rollup — but a
// plain copy is actually ideal for Node deployments where jsdom/undici
// have to remain in node_modules.
function copyTree(from, to) {
  fs.mkdirSync(to, { recursive: true });
  for (const entry of fs.readdirSync(from)) {
    const src = path.join(from, entry);
    const dst = path.join(to, entry);
    const stat = fs.statSync(src);
    if (stat.isDirectory()) copyTree(src, dst);
    else fs.copyFileSync(src, dst);
  }
}

const DIST_SRC = path.join(DIST_DIR, 'src');
console.log(`[build] copying src/ tree to ${DIST_SRC}`);
copyTree(path.join(HERE, 'src'), DIST_SRC);
// Replace the copied awsc-scripts.js with the bundled version
fs.copyFileSync(OUT_AWSC, path.join(DIST_SRC, 'lib', 'awsc-scripts.js'));
console.log(`[build] done`);
